        state = (r, c, dr, dc)
        if state in seen:
            continue
        seen.add(state)

        # Follow the beam until it strikes an 8.
        while 0 <= r + dr < h and 0 <= c + dc < w:
            r += dr
            c += dc
            if grid[r][c] == 8:
                break
            out[r][c] = 2
        else:
            continue

        # Sweep along the free row/column just before the obstacle.
        pr, pc = r - dr, c - dc
        for side in (-1, 1):
            rr, cc = pr, pc
            while True:
                rr += side * dc
                cc += side * dr
                if not (0 <= rr < h and 0 <= cc < w):
                    break
                out[rr][cc] = 2
                # A gap in the obstacle line is a passage for the beam.
                ar, ac = rr + dr, cc + dc
                if 0 <= ar < h and 0 <= ac < w and grid[ar][ac] == 0:
                    queue.append((rr, cc, dr, dc))
                    break
                if grid[rr][cc] == 8:
                    break

    return out
